import type { ShopeeOrder } from "../types/order";
import type { ScanSource } from "../types/scan";
import { normalizeTrackingCode } from "./normalization";
import { determineOrderStatus } from "./orderStatus";
import { commitScan } from "./storage";
export class CameraDebounce {
  private last = new Map<string, number>();
  ignore(code: string, now = Date.now()) {
    const previous = this.last.get(code);
    this.last.set(code, now);
    if (this.last.size > 100)
      for (const [key, time] of this.last)
        if (now - time > 1500) this.last.delete(key);
    return previous !== undefined && now - previous < 1500;
  }
}
export class ScanProcessor {
  private debounce = new CameraDebounce();
  private queue: Promise<unknown> = Promise.resolve();
  constructor(private orders: Map<string, ShopeeOrder>) {}
  processScan(rawCode: string, source: ScanSource = "manual") {
    const trackingCode = normalizeTrackingCode(rawCode);
    if (
      !trackingCode ||
      (source === "camera" && this.debounce.ignore(trackingCode))
    )
      return Promise.resolve(null);
    const job = this.queue.then(async () => {
      const order = this.orders.get(trackingCode);
      const availability = order ? determineOrderStatus(order) : null;
      const status = !order
        ? "UNKNOWN"
        : availability === "AVAILABLE"
          ? "ACCEPTED"
          : availability!;
      const saved = await commitScan({
        id: crypto.randomUUID(),
        trackingCode,
        status,
        scannedAt: Date.now(),
        orderId: order?.orderId,
        carrier: order?.carrier,
      });
      return { result: { ...saved.record, order }, counters: saved.counters };
    });
    this.queue = job.catch(() => undefined);
    return job;
  }
  async idle() {
    await this.queue;
  }
}
